-- 21 CMBO_SQL_M — FE 소비(useTabComboQueries filters / cellCboDataTp) + SHEET_COLUMNS 셀콤보 3본 [20260827]
-- ⚠ 공유 콤보(타 화면 소비)는 덮어쓰기 전 클라우드판 diff 확인: {"BucketType": 1, "DOM_EXP": 9, "MyDivision": 2}
-- ── SCM_ADM_CMBO_SQL_M 3행 MERGE (ON = PK 실측 ['SQL_ID', 'MDU_DIVS_CD']) [SQL_ID] ──
MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T USING (SELECT 'BucketType' AS SQL_ID, 'ALL' AS MDU_DIVS_CD, 'Bucket 유형 (D, W, M)' AS SQL_NM, 'SELECT SEGMENT1  AS CODE      , SEGMENT2  AS NAME FROM   SCM_ADM_LOOKUP_MASTER_DETAIL WHERE  1 = 1 AND    LOOKUP_TYPE = ''BUCKET_TYPE_CODE'' ORDER BY DISPLAY_SEQ' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'SYSTEM' AS CREATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'SYSTEM' AS LAST_UPDATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) S ON (T.SQL_ID=S.SQL_ID AND T.MDU_DIVS_CD=S.MDU_DIVS_CD)
WHEN MATCHED THEN UPDATE SET T.SQL_NM=S.SQL_NM, T.SQL_DTL_CTN=S.SQL_DTL_CTN, T.USE_YN=S.USE_YN, T.LAST_UPDATED_BY=S.LAST_UPDATED_BY, T.LAST_UPDATE_DATE=S.LAST_UPDATE_DATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE) VALUES (S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, S.CREATED_BY, S.CREATION_DATE, S.LAST_UPDATED_BY, S.LAST_UPDATE_DATE);
MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T USING (SELECT 'DOM_EXP' AS SQL_ID, 'CM' AS MDU_DIVS_CD, 'DOM/EXP (Domestic/Export)' AS SQL_NM, 'SELECT B.SEGMENT1 AS CODE, B.SEGMENT2 AS NAME FROM SCM_ADM_LOOKUP_MASTER A INNER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON A.LOOKUP_TYPE = B.LOOKUP_TYPE AND B.VALID_YN = ''Y'' WHERE A.LOOKUP_TYPE = ''DOM/EXP'' AND A.VALID_YN = ''Y'' ORDER BY B.DISPLAY_SEQ' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'admin' AS CREATED_BY, TO_DATE('2026-07-01 14:39:29','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'admin' AS LAST_UPDATED_BY, TO_DATE('2026-07-01 14:39:29','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) S ON (T.SQL_ID=S.SQL_ID AND T.MDU_DIVS_CD=S.MDU_DIVS_CD)
WHEN MATCHED THEN UPDATE SET T.SQL_NM=S.SQL_NM, T.SQL_DTL_CTN=S.SQL_DTL_CTN, T.USE_YN=S.USE_YN, T.LAST_UPDATED_BY=S.LAST_UPDATED_BY, T.LAST_UPDATE_DATE=S.LAST_UPDATE_DATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE) VALUES (S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, S.CREATED_BY, S.CREATION_DATE, S.LAST_UPDATED_BY, S.LAST_UPDATE_DATE);
MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M T USING (SELECT 'MyDivision' AS SQL_ID, 'DM' AS MDU_DIVS_CD, 'MyDivision' AS SQL_NM, '  SELECT  T1.DIVISION_ID AS CODE, T1.DIVISION_ID || '' '' || MIN(T1.DIVISION_NAME) AS NAME 	FROM  SCM_MST_DIVISION T1 	JOIN  SCM_ADM_USER_GR_UNIT_AUTH_MPG_M T2 	  ON  T1.DIVISION_ID = T2.UNIT_ID 	 AND  T2.UNIT_TP_CD = ''D''    WHERE  1=1 	 AND  T1.ATTRIBUTE3 <> ''EE'' 	 AND  T1.VALID_YN = ''Y'' 	 AND  T2.USE_YN = ''Y'' 	 AND  T2.USER_ID = @sesUserId GROUP BY  T1.DIVISION_ID, T1.ATTRIBUTE1 ORDER BY  T1.DIVISION_ID || '' '' || MIN(T1.DIVISION_NAME)' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'SYSTEM' AS CREATED_BY, TO_DATE('2026-02-13 12:05:25','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'SYSTEM' AS LAST_UPDATED_BY, TO_DATE('2026-02-13 12:05:25','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) S ON (T.SQL_ID=S.SQL_ID AND T.MDU_DIVS_CD=S.MDU_DIVS_CD)
WHEN MATCHED THEN UPDATE SET T.SQL_NM=S.SQL_NM, T.SQL_DTL_CTN=S.SQL_DTL_CTN, T.USE_YN=S.USE_YN, T.LAST_UPDATED_BY=S.LAST_UPDATED_BY, T.LAST_UPDATE_DATE=S.LAST_UPDATE_DATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE) VALUES (S.SQL_ID, S.MDU_DIVS_CD, S.SQL_NM, S.SQL_DTL_CTN, S.USE_YN, S.CREATED_BY, S.CREATION_DATE, S.LAST_UPDATED_BY, S.LAST_UPDATE_DATE);
COMMIT;
